using System;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using EternalSteam.OpenWorld;
public static class PolishHud06C{public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var e=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>().Sandbox.RailwayHud.GetComponent<RailwayOverview>().Editor;e.Description.textWrappingMode=TextWrappingModes.Normal;e.Feedback.textWrappingMode=TextWrappingModes.Normal;e.ScrollHint.textWrappingMode=TextWrappingModes.NoWrap;EditorUtility.SetDirty(e.Description);EditorUtility.SetDirty(e.Feedback);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return "Saved wrapped editor descriptions";}}
